package com.wizzadrds.theworldremembers.dream; import com.wizzadrds.theworldremembers.memory.*; import org.junit.jupiter.api.Test; import java.util.*; import static org.junit.jupiter.api.Assertions.*; class DreamManagerTest { @Test void fearDreamUsesThreatMemory(){var m=new DreamManager();UUID n=UUID.randomUUID(),s=UUID.randomUUID();var mem=new Memory(n,s,MemoryEventType.PLAYER_ATTACKED_NPC,10,MemoryImportance.IMPORTANT);var d=m.dreamFromMemory(n,mem,100);assertEquals(DreamType.FEAR,d.type());assertFalse(d.surreal());} @Test void impossibleDreamIsNotWorldFact(){var m=new DreamManager();UUID n=UUID.randomUUID(),s=UUID.randomUUID();var a=new Memory(n,s,MemoryEventType.PLAYER_GAVE_BREAD,1,MemoryImportance.IMPORTANT);var b=new Memory(n,s,MemoryEventType.NPC_MARRIED,2,MemoryImportance.IMPORTANT);var d=m.dreamImpossible(n,a,b,100);assertEquals(DreamType.IMPOSSIBLE,d.type());assertTrue(d.surreal());assertEquals(1,m.dreamsOf(n).size());} @Test void historyIsBounded(){var m=new DreamManager();UUID n=UUID.randomUUID(),s=UUID.randomUUID();for(int i=0;i<20;i++)m.dreamFromMemory(n,new Memory(n,s,MemoryEventType.NPC_DIED,i,MemoryImportance.IMPORTANT),i);assertEquals(16,m.dreamsOf(n).size());}}